#!/usr/bin/env node
// Build the "Start here" section of each per-repo README (repos/<name>/README.md) from
// estate.json and the repo's graph. The section sits between the BEGIN and END markers; the
// rest of the README comes from the regeneration recipe. A regeneration drops the markers, so
// the script inserts the section again before the first "##" heading.
// It also checks what a regeneration tends to get wrong in the rest of the README: an em dash
// (this repo's text uses none), and text that tells how to view the graphs (the section does
// that, and recipe step 3 says not to).
// Usage: node build-repo-readmes.mjs           rewrite the sections
//        node build-repo-readmes.mjs --check   exit 1 if a section is stale (CI)
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { loadEstate, root } from "./estate.mjs";

const SCRIPT = ".github/scripts/build-repo-readmes.mjs";
const BEGIN = `<!-- BEGIN start here: generated by ${SCRIPT} from estate.json and the graph. Do not edit by hand. -->`;
const END = "<!-- END start here -->";
const VOLUNTEER_GUIDE = "../../docs/contribute-to-greenstand.md";
const ALL_FIRST_ISSUES =
  "https://github.com/search?q=org%3AGreenstand+label%3A%22good+first+issue%22+is%3Aissue+is%3Aopen+archived%3Afalse&type=issues&s=updated&o=desc";
const CODE_OF_CONDUCT =
  "https://github.com/Greenstand/Greenstand-Overview/blob/master/License%2C%20Code%20of%20Conduct%20etc/CODE_OF_CONDUCT.md";

const check = process.argv.includes("--check");
const { estate, areas, count, errors } = loadEstate();

// Read a file of the docs repo, or record why it cannot be read.
function read(at, parse = (s) => s) {
  const file = join(root, at);
  if (!existsSync(file)) return errors.push(`${at} is missing`), null;
  try {
    return parse(readFileSync(file, "utf8"));
  } catch (e) {
    return errors.push(`${at}: ${e.message}`), null;
  }
}

// The path of the source repo's CONTRIBUTING.md, if it is a described file (a node in the
// graph), in the order of places that GitHub uses. The link points to the default branch
// (HEAD), which a new volunteer needs. If the file moves later, the drift report counts a
// removed described file.
const PLACES = [".github/contributing.md", "contributing.md", "docs/contributing.md"];
function contributingPath(name) {
  const at = `repos/${name}/knowledge-graph.json`;
  const graph = read(at, JSON.parse);
  if (graph === null) return null;
  if (!Array.isArray(graph.nodes)) return errors.push(`${at}: nodes must be a list`), null;
  const paths = graph.nodes.map((n) => n.filePath).filter(Boolean);
  for (const place of PLACES) {
    const path = paths.find((p) => p.toLowerCase() === place);
    if (path) return path;
  }
  return null;
}

function section({ name, source }) {
  const issues = `${source}/issues?q=is%3Aissue+is%3Aopen+label%3A%22good+first+issue%22`;
  const path = contributingPath(name);
  const readme = `[README](${source}#readme)`;
  const sourceDocs = path ? `the ${readme} and the [${path}](${source}/blob/HEAD/${path})` : `the ${readme}`;
  return [
    BEGIN,
    "",
    "## Start here",
    "",
    `- **Explore:** open the [interactive viewer](${estate.siteUrl}${name}/). It has a guided tour of the repo. Then read the [onboarding guide](./ONBOARDING.md) and the [glossary](./GLOSSARY.md).`,
    `- **Source repo:** [Greenstand/${name}](${source}). Read ${sourceDocs} of the source repo before you make a change.`,
    `- **First tasks:** pick one from the [open good first issues](${issues}) of ${name}, or from the [good first issues of all Greenstand repos](${ALL_FIRST_ISSUES}).`,
    `- **New to Greenstand?** Read [How to contribute to Greenstand](${VOLUNTEER_GUIDE}). It tells you how to join the community and where to get help. Everyone follows Greenstand's [Code of Conduct](${CODE_OF_CONDUCT}).`,
    "",
    END,
  ].join("\n");
}

const occurrences = (text, marker) => text.split(marker).length - 1;

// The first "##" heading outside a code fence, or null.
function firstHeading(lines) {
  let fence = false;
  for (let i = 0; i < lines.length; i++) {
    if (/^\s*(```|~~~)/.test(lines[i])) fence = !fence;
    if (!fence && lines[i].startsWith("## ")) return i;
  }
  return null;
}

// Replace the marked section, or insert it before the first "##" heading outside a code fence.
function splice(readme, text, at) {
  const begins = occurrences(readme, BEGIN);
  const ends = occurrences(readme, END);
  if (begins > 1 || ends > 1 || begins !== ends) {
    return errors.push(`${at}: ${begins} BEGIN and ${ends} END start-here markers; expected one of each, or none`), readme;
  }
  if (begins === 1) {
    const start = readme.indexOf(BEGIN);
    const stop = readme.indexOf(END);
    if (stop < start) return errors.push(`${at}: the END start-here marker comes before the BEGIN marker`), readme;
    return readme.slice(0, start) + text + readme.slice(stop + END.length);
  }
  const lines = readme.split("\n");
  const i = firstHeading(lines);
  if (i === null) return errors.push(`${at}: no "## " heading to put the Start here section before`), readme;
  return [...lines.slice(0, i), text, "", ...lines.slice(i)].join("\n");
}

// Check the README lines outside the section.
function checkText(readme, at) {
  let inSection = false;
  readme.split("\n").forEach((line, i) => {
    if (line === BEGIN) inSection = true;
    if (!inSection) {
      if (line.includes("\u2014")) errors.push(`${at}:${i + 1}: an em dash; use a colon, a comma, or two sentences`);
      if (line.includes(estate.siteUrl) || line.includes("understand-dashboard")) {
        errors.push(`${at}:${i + 1}: tells how to view the graphs; the Start here section does that`);
      }
    }
    if (line === END) inSection = false;
  });
}

const updates = [];
for (const repo of areas.flatMap((a) => a.repos)) {
  const at = `repos/${repo.name}/README.md`;
  const readme = read(at);
  if (readme === null) continue;
  checkText(readme, at);
  const before = errors.length;
  const next = splice(readme, section(repo), at);
  const lines = next.split("\n");
  if (errors.length === before && lines[firstHeading(lines)] !== "## Start here") {
    errors.push(`${at}: the Start here section must come before the other "## " headings`);
  }
  updates.push({ at, readme, next });
}

if (errors.length) {
  for (const e of errors) console.error(`error: ${e}`);
  process.exit(1);
}

const stale = updates.filter(({ readme, next }) => next !== readme);
if (check) {
  if (stale.length) {
    for (const { at } of stale) console.error(`error: the Start here section of ${at} is stale`);
    console.error(`Run: node ${SCRIPT}`);
    process.exit(1);
  }
  console.log(`Start here sections are current (${count} repos)`);
} else {
  for (const { at, next } of stale) writeFileSync(join(root, at), next);
  console.log(`wrote the Start here sections (${count} repos, ${stale.length} changed)`);
}
